<?php
namespace Tests\Feature;
use App\Models\{Address,PickupLocation,Product,ShippingMethod,ShippingProvince,ShippingRate,User};
use App\Services\ShippingRateService;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;
class ShippingPhase431Test extends TestCase {
 use RefreshDatabase;
 protected function setUp():void{parent::setUp();$this->withoutVite();$this->seed();}
 public function test_rate_priority_and_city_specificity_are_deterministic():void{$method=ShippingMethod::where('code','post_pishtaz')->firstOrFail();ShippingRate::create(['shipping_method_id'=>$method->id,'fee_toman'=>10000,'province_code'=>'tehran','priority'=>1,'is_enabled'=>true]);ShippingRate::create(['shipping_method_id'=>$method->id,'fee_toman'=>20000,'province_code'=>'tehran','city_code'=>'tehran','priority'=>2,'is_enabled'=>true]);$quote=app(ShippingRateService::class)->selected(100000,500,['province_code'=>'tehran','city_code'=>'tehran'],'post_pishtaz');$this->assertSame(20000,$quote['fee_toman']);$this->assertSame(2,$quote['snapshot']['rate_priority']);}
 public function test_authenticated_checkout_uses_owned_saved_address_snapshot():void{$user=User::factory()->create();$address=$user->addresses()->create(['nickname'=>'خانه','recipient_name'=>'مریم','phone'=>'09120000000','province'=>'تهران','city'=>'تهران','province_code'=>'tehran','city_code'=>'tehran','address'=>'خیابان نمونه','postal_code'=>'1234567890','is_default'=>true]);$product=Product::create(['name'=>'Shipping test','slug'=>'shipping-test','is_active'=>true]);$variant=$product->variants()->create(['sku'=>'SHIP-1','size'=>'3Y','color_name'=>'Blue','price_toman'=>1000,'stock_quantity'=>3,'is_active'=>true]);$this->actingAs($user)->withSession(['cart'=>[$variant->id=>1]])->post(route('checkout.store'),['address_id'=>$address->id,'phone'=>$address->phone,'shipping_method'=>'post_pishtaz'])->assertRedirect();$this->assertDatabaseHas('orders',['shipping_address_id'=>$address->id,'recipient_name'=>'مریم']);$this->assertSame('خیابان نمونه',$address->fresh()->address);}
 public function test_pickup_requires_active_location_and_snapshots_it_without_street_address():void{$method=ShippingMethod::where('code','pickup')->firstOrFail();$location=PickupLocation::create(['code'=>'main-store','name'=>'فروشگاه مرکزی','province_code'=>'tehran','city_code'=>'tehran','address'=>'نشانی فروشگاه','is_enabled'=>true,'sort_order'=>1]);$product=Product::create(['name'=>'Pickup test','slug'=>'pickup-test','is_active'=>true]);$variant=$product->variants()->create(['sku'=>'PICK-1','size'=>'4Y','color_name'=>'Red','price_toman'=>1000,'stock_quantity'=>2,'is_active'=>true]);$this->withSession(['cart'=>[$variant->id=>1]])->post(route('checkout.store'),['phone'=>'09120000000','shipping_method'=>$method->code,'pickup_location_id'=>$location->id])->assertRedirect();$this->assertDatabaseHas('orders',['shipping_method_code'=>'pickup','shipping_toman'=>0]);$snapshot=\App\Models\Order::latest('id')->value('shipping_address_snapshot');$this->assertSame('فروشگاه مرکزی',$snapshot['pickup_location']['name']);}
 public function test_address_endpoints_cannot_access_another_customer_address():void{$one=User::factory()->create();$two=User::factory()->create();$address=$two->addresses()->create(['recipient_name'=>'Other','phone'=>'09120000000','province'=>'تهران','city'=>'تهران','province_code'=>'tehran','city_code'=>'tehran','address'=>'Private','postal_code'=>'1234567890']);$this->actingAs($one)->delete(route('account.addresses.destroy',$address))->assertNotFound();$this->assertDatabaseHas('addresses',['id'=>$address->id]);}
}
